SELECT 
FROM visit v 
WHERE v.arrival_time >= #{dayStart}
  AND v.arrival_time <  #{dayEnd}

  AND v.clinic_id = #{clinicId}

ORDER BY v.arrival_time DESC

SELECT 
FROM visit v 
WHERE v.visit_id = #{visitId}

SELECT 
FROM visit v 
WHERE v.appointment_id = #{appointmentId}

SELECT 
FROM visit v 
WHERE v.employee_id = #{employeeId}
  AND v.arrival_time >= #{dayStart}
  AND v.arrival_time <  #{dayEnd}
ORDER BY v.arrival_time

SELECT COUNT(*) FROM statement
WHERE patient_id = #{patientId}
  AND status IN ('待出具', '已出具', '待支付')
